  for (const dato of registros) {
    mapa.set(dato.tema, (mapa.get(dato.tema) ?? 0) + dato.minutos);
  }
  return [...mapa];
}

function mejorRacha(datos, meta) {
  let actual = 0;
  let mejor = 0;
  for (const valor of datos) {
    actual = valor >= meta ? actual + 1 : 0;
    mejor = Math.max(mejor, actual);
  }
  return mejor;
}

function pasosMitad(opciones) {
  let pasos = 0;
  for (; opciones > 1; opciones = Math.ceil(opciones / 2)) pasos += 1;
  return pasos;
}

function compararCatalogos(sesiones, permitidas) {
  let lecturas = 0;
  const conLista = sesiones.filter(sesion => permitidas.some(modalidad => {
    lecturas += 1;
    return modalidad === sesion;
  })).length;
  const conjunto = new Set(permitidas);
  const conSet = sesiones.filter(sesion => conjunto.has(sesion)).length;
  return [conLista, conSet, lecturas, permitidas.length + sesiones.length];
}

function contieneDuracion(datos, objetivo) {
  let inicio = 0;
  let fin = datos.length - 1;
  while (inicio <= fin) {
    const medio = Math.floor((inicio + fin) / 2);
    if (datos[medio] === objetivo) return true;
    if (datos[medio] < objetivo) inicio = medio + 1;
    else fin = medio - 1;
  }
  return false;
}

function ordenarDuraciones(datos) {
  return datos.toSorted((a, b) => a - b);
}

function picoSemanal(datos, k) {
  if (k < 1 || k > datos.length) return null;
  let total = 0;
  for (let i = 0; i < k; i += 1) total += datos[i];
  let mejor = total;
  for (let i = k; i < datos.length; i += 1) {
    total += datos[i] - datos[i - k];
    mejor = Math.max(mejor, total);
  }
  return mejor;
}

function minutosDelArbol(nodo) {
  if (nodo === null) return 0;
  return nodo.hijos.reduce((total, hijo) => total + minutosDelArbol(hijo), nodo.minutos);
}

function historialDeMetas(inicio, acciones) {
  const pasado = [];
  let futuro = [];
  let actual = inicio;
  return acciones.map(accion => {
    switch (accion.tipo) {
      case "aplicar":
        pasado.push(actual);
        actual = accion.valor;
        futuro = [];
        break;
      case "deshacer":
        if (pasado.length > 0) {
          futuro.push(actual);
          actual = pasado.pop();
        }
        break;
      case "rehacer":
        if (futuro.length > 0) {
          pasado.push(actual);
          actual = futuro.pop();
        }
    }
    return actual;
  });
}

function primeraTareaEnNivel(raiz, objetivo) {
  if (raiz === null) return null;
  const cola = [[raiz, 0]];
  for (let i = 0; i < cola.length; i += 1) {
    const [nodo, nivel] = cola[i];
    if (nivel === objetivo) return nodo.id;
    for (const hijo of nodo.hijos) cola.push([hijo, nivel + 1]);
  }
  return null;
}

function tareasAlcanzables(conexiones, inicio) {
  const orden = [inicio];
  const vistos = new Set(orden);
  for (let i = 0; i < orden.length; i += 1) {
    const id = orden[i];
    for (const vecino of (Object.hasOwn(conexiones, id) ? conexiones[id] : [])) {
      if (vistos.has(vecino)) continue;
      vistos.add(vecino);
      orden.push(vecino);
    }
  }
  return orden;
}

function probarContadores(inicio, cambios) {
  const crear = base => {
    let total = base;
    return valor => { total += valor; return total; };
  };
  const primero = crear(inicio);
  const segundo = crear(0);
  return [primero(cambios[0]), segundo(cambios[1]), primero(cambios[2])];
}

function duracionDeSesion(inicio, cambios) {
  class Sesion {
    constructor(minutos) { this.total = minutos; }
    agregar(valor) { this.total += valor; return this.total; }
  }
  const sesion = new Sesion(inicio);
  return cambios.map(valor => sesion.agregar(valor));
}

function aplicarCambiosAlPlan(inicio, cambios) {
  class CuentaPlan {
    constructor(saldo) { this.saldo = saldo; }
    mover(valor) { this.saldo += valor; return this.saldo; }
  }
  const cuenta = new CuentaPlan(inicio);
  const aplicar = cuenta.mover.bind(cuenta);
  return cambios.map(aplicar);
}

function fechaEnZona(iso, zona) {
  const partes = new Intl.DateTimeFormat("en", { timeZone: zona, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date(iso));
  const leer = tipo => partes.find(parte => parte.type === tipo).value;
  return `${leer("year")}-${leer("month")}-${leer("day")}`;
}

function siguienteCodigo(texto, salto) {
  const siguiente = BigInt(texto) + BigInt(salto);
  return String(siguiente);
}

function modoDelPlan(argumentos) {
  if (argumentos.length !== 1) return "ayuda";
  switch (argumentos[0]) {
    case "--resumen": return "resumen";
    case "--validar": return "validar";
    default: return "ayuda";
  }
}

function archivoDelPlan(texto) {
  const base = texto.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return `${base || "plan"}.json`;
}

function modeloPlan(minutos, dias) {
  const total = calcularTotal(minutos, dias);
  const estado = recomendar(minutos);
  const alcanza = minutos >= 30;
  return { total, estado, alcanza };
}

function pruebasUmbral(objetivo) {
  const entradas = [objetivo - 1, objetivo, objetivo + 1];
  return entradas.map((entrada, indice) => [entrada, indice !== 0]);
}

function diasDelFormulario(texto) {
  const dias = Number(texto);
  return texto.trim() !== "" && Number.isInteger(dias) && dias >= 0 && dias <= 7 ? dias : null;
}

function etiquetaDeEstado(estado, dias) {
  const unidad = dias === 1 ? "día" : "días";
  return `${estado} · ${dias} ${unidad}`;
}

function lineasDelPanel(nombre, minutos, dias) {
  const { estado, total } = modeloPlan(minutos, dias);
  return [nombre, etiquetaDeEstado(estado, dias), `${total} min`];
}

function aplicarFormulario(nombre, minutos, dias) {
  const diasValidos = diasDelFormulario(dias);
  const limpio = nombre.trim();
  if (!limpio || !minutosValidos(minutos) || diasValidos === null) return null;
  return { nombre: limpio, minutos: Number(minutos), dias: diasValidos };
}

function reducirSesiones(datos, accion) {
  switch (accion.tipo) {
    case "deshacer": return datos.slice(0, -1);
    case "agregar":
      if (Number.isInteger(accion.minutos) && accion.minutos >= 0 && accion.minutos <= 120) return [...datos, accion.minutos];
  }
  return [...datos];
}

function restaurarSesiones(texto) {
  const vacio = estado => ({ estado, sesiones: [] });
  if (texto === null) return vacio("nuevo");
  try {
    const copia = JSON.parse(texto);
    if (copia?.version !== 1 || !Array.isArray(copia.sesiones)) return vacio("invalido");
    const sesiones = importarMinutos(JSON.stringify(copia.sesiones));
    return sesiones === null ? vacio("invalido") : { estado: "guardado", sesiones };
  } catch { return vacio("invalido"); }
}

function ordenDeTareas(etiqueta) {
  const pasos = [etiqueta + " inicia"];
  const termina = new Promise(resolve => {
    setTimeout(() => { pasos.push("tarea"); resolve(pasos); }, 0);
  });
  Promise.resolve().then(() => pasos.push("microtarea"));
  pasos.push("fin síncrono");
  return termina;
}

function combinarEstimaciones(a, b) {
  const leer = n => n < 0 ? Promise.reject(Error("sin dato")) : Promise.resolve(n);
  return Promise.all([leer(a), leer(b)])
    .then(([primero, segundo]) => primero + segundo)
    .catch(() => "Sin estimación");
}

function urlSugerencias(tema, limite) {
  return `/sugerencias?tema=${encodeURIComponent(tema)}&limite=${limite}`;
}

async function pedirSugerencia(url) {
  try {
    const respuesta = await fetch(url);
    if (!respuesta.ok) return `HTTP ${respuesta.status}`;
    const dato = await respuesta.json();
    return typeof dato?.titulo === "string" && dato.titulo.trim() !== "" ? dato.titulo : "Sin sugerencia";
  } catch { return "Sin sugerencia"; }
}

function resultadoVigente(respuestas, version) {
  return respuestas.reduce((visible, respuesta) =>
    respuesta.version === version ? respuesta.texto : visible, "Pendiente");
}

function resumenIntegrado(nombre, minutos, dias) {
  const datos = aplicarFormulario(nombre, minutos, dias);
  return datos === null ? "Entrada inválida" : lineasDelPanel(datos.nombre, datos.minutos, datos.dias).join(" · ");
}

function erroresDelPlan(nombre, minutos, dias) {
  const campos = [["nombre", nombre.trim() !== ""], ["minutos", minutosValidos(minutos)], ["dias", diasDelFormulario(dias) !== null]];
  return campos.filter(par => !par[1]).map(par => par[0]);
}

function vistaTrasEnvio(anterior, candidata, errores) {
  const hayErrores = errores.length > 0;
  const vista = hayErrores ? anterior : candidata;
  const foco = errores[0] ?? null;
  return { vista, foco, errores: [...errores] };
}

function compactarCambios(cambios) {
  const ultimo = new Map(cambios.map(dato => [dato.id, dato.minutos]));
  return [...ultimo];
}

function informePlan(datos, objetivo) {
  const [total, cumplen] = resumir(datos, objetivo);
  const mayor = maximo(datos);
  const racha = mejorRacha(datos, objetivo);
  return { total, cumplen, mayor, racha };
}

function exportarPlan(sesiones) {
  return JSON.stringify({ version: 1, sesiones: [...sesiones] });
}

function procesarReservas(salas, pedidos) {
  const disponibles = new Map(salas.map(sala => [sala.id, sala.cupos]));
  const resultados = pedidos.map(({ sala, plazas }) => {
    if (!Number.isInteger(plazas) || plazas < 1) return "invalida";
    if (!disponibles.has(sala)) return "desconocida";
    const cupo = disponibles.get(sala);
    if (cupo < plazas) return "agotada";
    disponibles.set(sala, cupo - plazas);
    return "aceptada";
  });
  return { cupos: [...disponibles], resultados };
}

