function resolverCaso(inventario, texto) {
  const invalida = () => ({ estado: "invalida", inventario });
  let documento;
  try {
    documento = JSON.parse(texto);
  } catch {
    return invalida();
  }
  if (documento?.version !== 2 || !Array.isArray(documento.devoluciones)) return invalida();
  const disponible = new Map(inventario);
  for (const cambio of documento.devoluciones) {
    if (!cambio || !disponible.has(cambio.id) ||
        !Number.isInteger(cambio.unidades) || cambio.unidades < 1) return invalida();
    disponible.set(cambio.id, disponible.get(cambio.id) + cambio.unidades);
  }
  return { estado: "aplicada", inventario: [...disponible] };
}
